-- Additive: professional functions and scheduled physical/psychology sessions.
CREATE TABLE staff_functions (id uuid PRIMARY KEY, "coachId" uuid NOT NULL REFERENCES coaches(id), kind text NOT NULL CHECK(kind IN ('COACH','PHYSICAL','PSYCHOLOGY')), active boolean NOT NULL DEFAULT true, UNIQUE("coachId",kind));
CREATE TABLE support_sessions (id uuid PRIMARY KEY, "seasonId" uuid NOT NULL REFERENCES seasons(id), "coachId" uuid NOT NULL REFERENCES coaches(id), "teamId" uuid REFERENCES teams(id), "venueId" uuid NOT NULL REFERENCES venues(id), kind text NOT NULL CHECK(kind IN ('PHYSICAL','PSYCHOLOGY')), title text NOT NULL, "startsAt" timestamptz NOT NULL, "endsAt" timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('SCHEDULED','CANCELLED')), CHECK("startsAt" < "endsAt"));
CREATE TABLE support_participants (id uuid PRIMARY KEY, "sessionId" uuid NOT NULL REFERENCES support_sessions(id), "playerSeasonId" uuid NOT NULL REFERENCES player_seasons(id), mode text NOT NULL CHECK(mode IN ('REGULAR','GUEST','RECOVERY')), active boolean NOT NULL DEFAULT true, UNIQUE("sessionId","playerSeasonId"));
CREATE TABLE support_attendance (id uuid PRIMARY KEY, "sessionId" uuid NOT NULL REFERENCES support_sessions(id), "playerSeasonId" uuid NOT NULL REFERENCES player_seasons(id), status text NOT NULL CHECK(status IN ('PRESENT','ABSENT','EXCUSED')), UNIQUE("sessionId","playerSeasonId"));
